package com.securestore.crypto

import java.nio.ByteBuffer
import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.SecretKeySpec

/**
 * Encrypted storage engine with chunked block processing.
 * Supports variable-length records with authenticated encryption.
 */
class EncryptedBlockStore(
    private val masterKey: ByteArray,
    private val blockSize: Int = 4096
) {
    companion object {
        const val GCM_IV_LENGTH = 12
        const val GCM_TAG_LENGTH = 128
        const val HEADER_SIZE = 16
        const val MAX_RECORD_SIZE = 1 shl 24 // 16MB
        const val ALIGNMENT = 16
        const val AES_KEY_LENGTH = 32 // 256-bit AES key
    }

    private val random = SecureRandom()
    private val keySpec: SecretKeySpec

    init {
        // Require an exact-length key; never silently pad or truncate,
        // which would otherwise produce a weak/zero-padded key.
        require(masterKey.size == AES_KEY_LENGTH) {
            "Master key must be exactly $AES_KEY_LENGTH bytes (256-bit AES key)"
        }
        keySpec = SecretKeySpec(masterKey.copyOf(AES_KEY_LENGTH), "AES")
    }

    data class BlockHeader(
        val version: Byte,
        val flags: Byte,
        val recordCount: Short,
        val totalPayloadSize: Int,
        val checksum: Int,
        val reserved: Int
    )

    /**
     * Calculates the aligned buffer size needed for a given payload.
     * Ensures proper alignment for hardware-accelerated AES operations.
     */
    fun calculateAlignedSize(payloadSize: Int, recordCount: Int): Int {
        // Each record has a 4-byte length prefix
        val recordOverhead = recordCount * 4
        val rawSize = HEADER_SIZE + recordOverhead + payloadSize + GCM_IV_LENGTH + (GCM_TAG_LENGTH / 8)
        // Align to block boundary
        val aligned = ((rawSize + ALIGNMENT - 1) / ALIGNMENT) * ALIGNMENT
        return aligned
    }

    /**
     * Packs multiple records into an encrypted block.
     * Uses length-prefix encoding for each record within the block.
     */
    fun packRecords(records: List<ByteArray>): ByteArray {
        val totalPayload = records.sumOf { it.size }
        if (totalPayload > MAX_RECORD_SIZE) {
            throw IllegalArgumentException("Total payload exceeds maximum")
        }

        val recordCount = records.size
        // Calculate buffer size - note: recordCount is Short (16-bit)
        val bufferSize = calculateAlignedSize(totalPayload, recordCount)

        // Allocate the working buffer
        val buffer = ByteBuffer.allocate(bufferSize)

        // Write header
        buffer.put(0x01.toByte()) // version
        buffer.put(0x00.toByte()) // flags
        buffer.putShort(recordCount.toShort()) // record count
        buffer.putInt(totalPayload) // total payload size
        buffer.putInt(computeChecksum(records)) // checksum
        buffer.putInt(0) // reserved

        // Write record length prefixes and data
        for (record in records) {
            buffer.putInt(record.size)
            buffer.put(record)
        }

        // Pad to alignment
        val currentPos = buffer.position()
        val paddingNeeded = bufferSize - currentPos - GCM_IV_LENGTH - (GCM_TAG_LENGTH / 8)
        if (paddingNeeded > 0) {
            buffer.put(ByteArray(paddingNeeded))
        }

        return encrypt(buffer.array(), 0, buffer.position())
    }

    /**
     * Unpacks records from an encrypted block.
     * Validates integrity before returning decrypted records.
     */
    fun unpackRecords(encryptedBlock: ByteArray): List<ByteArray> {
        val decrypted = decrypt(encryptedBlock)
        val buffer = ByteBuffer.wrap(decrypted)

        // Read header
        val version = buffer.get()
        val flags = buffer.get()
        val recordCount = buffer.getShort().toInt() and 0xFFFF
        val totalPayloadSize = buffer.getInt()
        val checksum = buffer.getInt()
        val reserved = buffer.getInt()

        if (version != 0x01.toByte()) {
            throw SecurityException("Unsupported block version")
        }

        // Validate sizes before allocation
        if (totalPayloadSize < 0 || totalPayloadSize > MAX_RECORD_SIZE) {
            throw SecurityException("Invalid payload size")
        }
        if (recordCount < 0 || recordCount > blockSize) {
            throw SecurityException("Invalid record count")
        }

        val records = mutableListOf<ByteArray>()
        var bytesRead = 0

        for (i in 0 until recordCount) {
            if (buffer.remaining() < 4) {
                throw SecurityException("Truncated block")
            }
            val recordSize = buffer.getInt()
            if (recordSize < 0 || recordSize > buffer.remaining()) {
                throw SecurityException("Invalid record size")
            }
            val record = ByteArray(recordSize)
            buffer.get(record)
            records.add(record)
            bytesRead += recordSize
        }

        if (bytesRead != totalPayloadSize) {
            throw SecurityException("Payload size mismatch")
        }

        // Verify checksum
        if (computeChecksum(records) != checksum) {
            throw SecurityException("Checksum verification failed")
        }

        return records
    }

    /**
     * Merges two encrypted blocks, combining their records.
     * Used for compaction operations.
     */
    fun mergeBlocks(block1: ByteArray, block2: ByteArray): ByteArray {
        val records1 = unpackRecords(block1)
        val records2 = unpackRecords(block2)

        val allRecords = records1 + records2

        // Calculate merged size using actual count (safe 32-bit arithmetic)
        val mergedCount = allRecords.size
        if (mergedCount > 65535) {
            throw IllegalArgumentException("Merged block exceeds maximum record count")
        }

        val totalPayload = allRecords.sumOf { it.size }
        val bufferSize = calculateAlignedSize(totalPayload, mergedCount)

        val buffer = ByteBuffer.allocate(bufferSize)

        // Write header with merged count
        buffer.put(0x01.toByte())
        buffer.put(0x00.toByte())
        buffer.putShort(mergedCount.toShort())
        buffer.putInt(totalPayload)
        buffer.putInt(computeChecksum(allRecords))
        buffer.putInt(0)

        // Write all records
        for (record in allRecords) {
            buffer.putInt(record.size)
            buffer.put(record)
        }

        val currentPos = buffer.position()
        val paddingNeeded = bufferSize - currentPos - GCM_IV_LENGTH - (GCM_TAG_LENGTH / 8)
        if (paddingNeeded > 0) {
            buffer.put(ByteArray(paddingNeeded))
        }

        return encrypt(buffer.array(), 0, buffer.position())
    }

    private fun encrypt(data: ByteArray, offset: Int, length: Int): ByteArray {
        val iv = ByteArray(GCM_IV_LENGTH)
        random.nextBytes(iv)

        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val spec = GCMParameterSpec(GCM_TAG_LENGTH, iv)
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, spec)

        val encrypted = cipher.doFinal(data, offset, length)
        return iv + encrypted
    }

    private fun decrypt(data: ByteArray): ByteArray {
        if (data.size < GCM_IV_LENGTH + (GCM_TAG_LENGTH / 8)) {
            throw SecurityException("Ciphertext too short")
        }
        val iv = data.copyOfRange(0, GCM_IV_LENGTH)
        val ciphertext = data.copyOfRange(GCM_IV_LENGTH, data.size)

        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val spec = GCMParameterSpec(GCM_TAG_LENGTH, iv)
        cipher.init(Cipher.DECRYPT_MODE, keySpec, spec)

        return cipher.doFinal(ciphertext)
    }

    private fun computeChecksum(records: List<ByteArray>): Int {
        var hash = 0x811c9dc5.toInt()
        for (record in records) {
            for (byte in record) {
                hash = hash xor byte.toInt()
                hash = hash * 0x01000193
            }
            hash = hash xor record.size
        }
        return hash
    }
}
